/**
 * The docs site's pages and sidebar, in one place. Plain TypeScript with no Astro imports, so
 * `tests/site.test.ts` (run by `pnpm test` at the repo root) can check it against the repo.
 *
 * Each page is a markdown file read in place from the repo. Paths are relative to the repo root.
 * The tutorial pages (`packages/okb/examples/<name>/tutorial/N-slug.md`) are generated by `pnpm example`, so build
 * them before the site.
 */

export interface Page {
  /** The URL path, with leading and trailing slashes. */
  route: string;
  /** The markdown file it renders, relative to the repo root. */
  source: string;
  /** The sidebar label. The page's own title is its first `# ` heading. */
  label: string;
  /** One plain sentence on what a reader gets from the page (about 20 words). It feeds `/llms.txt`. */
  summary: string;
}

